set -euo pipefail
rm -rf /tmp/reqwest-timeout-probe
mkdir -p /tmp/reqwest-timeout-probe/src
cat > /tmp/reqwest-timeout-probe/Cargo.toml <<'EOF'
[package]
name = "reqwest-timeout-probe"
version = "0.1.0"
edition = "2024"

[dependencies]
reqwest = { version = "=0.12.28", default-features = false, features = ["rustls-tls"] }
tokio = { version = "1", features = ["macros", "rt-multi-thread", "net", "time"] }
EOF
cat > /tmp/reqwest-timeout-probe/src/main.rs <<'EOF'
use std::error::Error;
use std::time::{Duration, Instant};
use tokio::net::TcpListener;

#[tokio::main]
async fn main() {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move {
        let (_stream, _) = listener.accept().await.unwrap();
        tokio::time::sleep(Duration::from_secs(90)).await;
    });

    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(600))
        .build()
        .unwrap();
    let started = Instant::now();
    let error = client
        .post(format!("http://{addr}/stall"))
        .body(vec![0_u8; 128 * 1024 * 1024])
        .send()
        .await
        .expect_err("server intentionally never reads request body");
    println!(
        "elapsed={:?} display={error}; debug={error:?}; timeout={} connect={} request={} body={}",
        started.elapsed(),
        error.is_timeout(),
        error.is_connect(),
        error.is_request(),
        error.is_body()
    );
    let mut source = error.source();
    let mut depth = 0;
    while let Some(cause) = source {
        println!("source[{depth}]={cause}; debug={cause:?}");
        source = cause.source();
        depth += 1;
    }
}
EOF
cargo run --quiet --manifest-path /tmp/reqwest-timeout-probe/Cargo.toml

